const { useState } = React;

function App() {
  const [page, setPage] = useState("home");
  const [sendAmount, setSendAmount] = useState("");
  const [sendTo, setSendTo] = useState("");
  const [errors, setErrors] = useState({});
  const [balance, setBalance] = useState(2450);

  const activity = [
    { id: 1, label: "Coffee", amount: -4 },
    { id: 2, label: "Salary", amount: 1200 },
    { id: 3, label: "Groceries", amount: -36 },
  ];

  function validateSend() {
    const newErrors = {};
    if (!sendTo.trim()) {
      newErrors.sendTo = "Recipient is required.";
    }
    if (!sendAmount.trim()) {
      newErrors.sendAmount = "Amount is required.";
    } else if (isNaN(sendAmount) || Number(sendAmount) <= 0) {
      newErrors.sendAmount = "Enter a valid positive number.";
    } else if (Number(sendAmount) > balance) {
      newErrors.sendAmount = "Insufficient balance.";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleSendSubmit(e) {
    e.preventDefault();
    if (validateSend()) {
      const amountNum = Number(sendAmount);
      setBalance(prev => prev - amountNum);
      // Add to activity list could be implemented here if needed
      setSendAmount("");
      setSendTo("");
      setErrors({});
      setPage("home");
    }
  }

  const styles = {
    container: {
      maxWidth: 400,
      margin: "0 auto",
      padding: 16,
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif",
      backgroundColor: "#fff",
      color: "#222",
      minHeight: "100vh",
      boxSizing: "border-box",
    },
    header: {
      display: "flex",
      alignItems: "center",
      padding: "8px 0",
      borderBottom: "1px solid #ddd",
      fontSize: 18,
      fontWeight: "500",
    },
    menuIcon: {
      fontSize: 24,
      cursor: "pointer",
      marginRight: 12,
      userSelect: "none",
    },
    balanceCard: {
      border: "1.5px solid #888",
      borderRadius: 12,
      padding: 20,
      marginTop: 16,
      fontSize: 18,
      fontWeight: "500",
      userSelect: "none",
    },
    balanceAmount: {
      fontSize: 32,
      fontWeight: "700",
      marginTop: 8,
      userSelect: "text",
    },
    buttonsRow: {
      display: "flex",
      justifyContent: "space-between",
      marginTop: 16,
      gap: 12,
    },
    button: {
      flex: 1,
      padding: "10px 0",
      borderRadius: 8,
      border: "1.5px solid #888",
      backgroundColor: "#fff",
      fontSize: 16,
      fontWeight: "600",
      cursor: "pointer",
      userSelect: "none",
      transition: "background-color 0.2s, border-color 0.2s",
    },
    buttonPrimary: {
      backgroundColor: "#6f42c1",
      borderColor: "#6f42c1",
      color: "#fff",
    },
    heading: {
      marginTop: 24,
      fontWeight: "600",
      fontSize: 20,
      userSelect: "none",
    },
    activityList: {
      marginTop: 8,
      paddingLeft: 20,
      userSelect: "none",
    },
    activityItem: {
      marginBottom: 6,
      fontSize: 16,
    },
    sendForm: {
      marginTop: 24,
      display: "flex",
      flexDirection: "column",
      gap: 12,
    },
    label: {
      fontWeight: "600",
      fontSize: 14,
      userSelect: "none",
    },
    input: {
      padding: "8px 10px",
      fontSize: 16,
      borderRadius: 6,
      border: "1.5px solid #ccc",
      outline: "none",
      userSelect: "text",
    },
    inputError: {
      borderColor: "#d9534f",
      backgroundColor: "#f9d6d5",
    },
    errorMsg: {
      color: "#d9534f",
      fontSize: 13,
      marginTop: 2,
      userSelect: "none",
    },
    sendButtonsRow: {
      display: "flex",
      justifyContent: "space-between",
      marginTop: 16,
      gap: 12,
    },
  };

  if (page === "send") {
    return (
      <main style={styles.container} aria-label="Send Money Page">
        <header style={styles.header}>
          <button
            onClick={() => setPage("home")}
            aria-label="Back to Home"
            style={{ ...styles.menuIcon, fontWeight: "700" }}
          >
            10
          </button>
          <h1 style={{ margin: 0, fontSize: 20, userSelect: "none" }}>Send Money</h1>
        </header>
        <form onSubmit={handleSendSubmit} style={styles.sendForm} noValidate>
          <label htmlFor="sendTo" style={styles.label}>
            Recipient
          </label>
          <input
            id="sendTo"
            name="sendTo"
            type="text"
            value={sendTo}
            onChange={e => setSendTo(e.target.value)}
            style={{
              ...styles.input,
              ...(errors.sendTo ? styles.inputError : {}),
            }}
            aria-describedby={errors.sendTo ? "sendTo-error" : undefined}
            aria-invalid={errors.sendTo ? "true" : "false"}
            autoComplete="off"
          />
          {errors.sendTo && (
            <p id="sendTo-error" role="alert" style={styles.errorMsg}>
              {errors.sendTo}
            </p>
          )}

          <label htmlFor="sendAmount" style={styles.label}>
            Amount ($)
          </label>
          <input
            id="sendAmount"
            name="sendAmount"
            type="number"
            min="0"
            step="0.01"
            value={sendAmount}
            onChange={e => setSendAmount(e.target.value)}
            style={{
              ...styles.input,
              ...(errors.sendAmount ? styles.inputError : {}),
            }}
            aria-describedby={errors.sendAmount ? "sendAmount-error" : undefined}
            aria-invalid={errors.sendAmount ? "true" : "false"}
            autoComplete="off"
          />
          {errors.sendAmount && (
            <p id="sendAmount-error" role="alert" style={styles.errorMsg}>
              {errors.sendAmount}
            </p>
          )}

          <div style={styles.sendButtonsRow}>
            <button
              type="submit"
              style={{ ...styles.button, ...styles.buttonPrimary }}
            >
              Send
            </button>
            <button
              type="button"
              onClick={() => {
                setSendAmount("");
                setSendTo("");
                setErrors({});
                setPage("home");
              }}
              style={styles.button}
            >
              Cancel
            </button>
          </div>
        </form>
      </main>
    );
  }

  // Home page
  return (
    <main style={styles.container} aria-label="Mobile Wallet Home Screen">
      <header style={styles.header}>
        <button
          aria-label="Open menu"
          style={styles.menuIcon}
          onClick={() => alert("Menu clicked")}
          type="button"
        >
          61;
        </button>
        <h1 style={{ margin: 0, userSelect: "none", fontWeight: "500" }}>Hi, Sam</h1>
      </header>

      <section style={styles.balanceCard} aria-label="Balance">
        <p style={{ margin: 0, fontStyle: "italic" }}>Balance</p>
        <p style={styles.balanceAmount} aria-live="polite">
          ${balance.toLocaleString()}
        </p>
      </section>

      <section style={styles.buttonsRow}>
        <button
          style={styles.button}
          onClick={() => setPage("send")}
          type="button"
          aria-label="Send money"
        >
          Send
        </button>
        <button
          style={styles.button}
          onClick={() => alert("Request money clicked")}
          type="button"
          aria-label="Request money"
        >
          Request
        </button>
      </section>

      <section aria-label="Activity">
        <h2 style={styles.heading}>Activity</h2>
        <ul style={styles.activityList}>
          {activity.map(({ id, label, amount }) => (
            <li key={id} style={styles.activityItem}>
              {label} {amount < 0 ? `- $${Math.abs(amount)}` : `+ $${amount}`}
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

